import{B as e,Q as t,s as n,z as r}from"./chunks/framework.DaWAnZmO.js";var i=JSON.parse(`{"title":"Cluster Decisions","description":"","frontmatter":{"title":"Cluster Decisions"},"headers":[],"relativePath":"architecture/cluster-decisions.md","filePath":"architecture/cluster-decisions.md"}`),a={name:`architecture/cluster-decisions.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="cluster-decisions" tabindex="-1">Cluster Decisions <a class="header-anchor" href="#cluster-decisions" aria-label="Permalink to &quot;Cluster Decisions&quot;">​</a></h1><p>How OmniRoute behaves when running as multiple nodes.</p><h2 id="quorum" tabindex="-1">Quorum <a class="header-anchor" href="#quorum" aria-label="Permalink to &quot;Quorum&quot;">​</a></h2><p>Routing decisions are local. There is no global lock.</p><ul><li>Each node reads its own SQLite (or its own row in shared Postgres)</li><li>Quota counters are eventually consistent</li><li>Provider failover is per-node, decided in &lt;2 ms</li></ul><h2 id="cross-region-failover" tabindex="-1">Cross-region failover <a class="header-anchor" href="#cross-region-failover" aria-label="Permalink to &quot;Cross-region failover&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client → nearest region (geo DNS) → node picks provider</span></span>
<span class="line"><span>                                          ↓</span></span>
<span class="line"><span>                              if all providers exhausted → 503</span></span></code></pre></div><p>Failover is <strong>fail-stop</strong>: if a node cannot reach any provider, it returns 503 immediately. It does NOT silently route to a degraded provider.</p><h2 id="lockless-quorum" tabindex="-1">Lockless quorum <a class="header-anchor" href="#lockless-quorum" aria-label="Permalink to &quot;Lockless quorum&quot;">​</a></h2><p>There is no leader election. Every node is a peer.</p><p>Why: routing decisions are stateless. A peer can lose 50% of the cluster and still serve the same requests.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};